T[13423]={"^Has slain hundreds of outlaws in their quest to uphold peace and defend the weak%.%s*$","Ha eliminado a cientos de forajidos en su búsqueda por mantener la paz y defender a los débiles."}
T[13424]={"^Increases luck gained from kills by (.-)%%%.%s*$","Aumenta la suerte obtenida de las muertes en un {{1}}%."}
T[13425]={"^Participating in the Ironman Challenge%. Upon Death this character is permanently dead! \n\nOnly attackable by other Ironman players, while leveling%. through honorable combat%.\nOnce reaching max level, you can be attacked by all other heroes%.%s*$","Participando en el Desafío Ironman. ¡Al morir, este personaje morirá permanentemente!\n\nSolo otros jugadores Ironman pueden atacarte mientras subes de nivel, mediante combate honorable.\nUna vez alcanzado el nivel máximo, todos los demás héroes podrán atacarte."}
T[13426]={"^Participating in the Survivalist Challenge%. Upon Death this character is permanently dead! Can only form groups with other survivalists%.%s*$","Participas en el Desafío del Superviviente. ¡Al morir, este personaje morirá permanentemente! Solo puedes formar grupos con otros supervivientes."}
T[13427]={"^Increases reputation gained from kills and quests by (.-)%%%.%s*$","Aumenta la reputación ganada por muertes y misiones en un {{1}}%."}
T[13428]={"^Nether energies weaken the Azeroth magic imbued in your level 60 Epic Gear%. Upon reaching level 70 this effect will increase from 0%% to 3%% per piece of equipped 60 Epic Gear%.\n\nDamage done reduced by (.-)%%%.\nHealing done reduced by (.-)%%%.\nDamage taken increased by (.-)%%%.%s*$","Las energías del Nexo debilitan la magia de Azeroth que impregna tu equipo épico de nivel 60. Al alcanzar el nivel 70, este efecto aumentará desde 0% hasta 3% por cada pieza de equipo épico 60 equipada.\n\nEl daño realizado disminuye en {{1}}%.\nLa sanación realizada disminuye en {{2}}%.\nEl daño recibido aumenta en {{3}}%."}
T[13429]={"^Incite Chaos burns in your veins, forcing you to move with (.-)%% movement speed and leaving a path of burning shadows dealing shadow damage every (.-) seconds%.%s*$","Incitar el Caos arde en tus venas, obligándote a moverte con una velocidad de movimiento reducida en {{1}}% y dejando un camino de sombras ardientes que inflige daño de Sombras cada {{2}} segundos."}
T[13430]={"^Inflicts (.-) Shadow damage every (.-) sec%.\nShadows accumulate beneath you every (.-) seconds%.%s*$","Inflige {{1}} de daño de Sombras cada {{2}} seg.\nLas Sombras se acumulan bajo tus pies cada {{3}} segundos."}
T[13431]={"^Cannot attack or be attacked by other players%.%s*$","No puedes atacar ni ser atacado por otros jugadores."}
T[13432]={"^Taking (.-) fire damage (.-) seconds%.%s*$","Recibes {{1}} de daño de fuego en {{2}} segundos."}
T[13433]={"^Cannot resummon Khadgar's Servant for the duration of this debuff%.%s*$","No puedes volver a invocar al Sirviente de Khadgar durante la duración de este perjuicio."}
T[13434]={"^(.-)%% health and (.-)%% mana regenerated every 2 sec%.\nDamage taken reduced by (.-)%%%.%s*$","{{1}}% salud y {{2}}% maná se regeneran cada 2 seg.\nEl daño recibido se reduce en {{3}}%."}
T[13435]={"^(.-)%% health and (.-)%% mana regenerated every 2 sec%.%s*$","{{1}}% salud y {{2}}% maná regenerado cada 2 seg."}
T[13436]={"^Attack and casting speeds increased by (.-)%%%.Movement speed increased by (.-)%%%.%s*$","La velocidad de ataque y de lanzamiento aumenta un {{1}}%.\nLa velocidad de movimiento aumenta un {{2}}%."}
T[13437]={"^Deals (.-) fire damage on hit%.\nAbsorb up to (.-) fire damage%.\n\nApplies Molten Skin on removal%s*$","Inflige {{1}} de daño de fuego al golpear.\nAbsorbe hasta {{2}} de daño de fuego.\n\nAplica Piel fundida al desaparecer"}
T[13438]={"^Size increased by (.-)%%%.\nDamage increased by (.-)%%%.\nSwing speed reduced by (.-)%%%.\n\nThis effect stacks up to (.-) times on a single target%.%s*$","El tamaño aumenta un {{1}}%.\nEl daño aumenta un {{2}}%.\nLa velocidad de ataque se reduce un {{3}}%.\n\nEste efecto se acumula hasta {{4}} veces en un solo objetivo."}
T[13439]={"^(.-) Physical damage inflicted every (.-) sec%.\n\nStacks up to (.-) times%.%s*$","Inflige {{1}} de daño físico cada {{2}} seg.\n\nSe acumula hasta {{3}} veces."}
T[13440]={"^Kept alive by necromantic magics%.%s*$","Mantenido con vida por magias nigrománticas."}
T[13441]={"^Armored Crypt Swarmer takes (.-)%% more damage%.%s*$","El Enjambre de la cripta blindada recibe un {{1}}% más de daño."}
