T[13443]={"^Chance to hit with spells and abilities reduced by (.-)%%%.\nPeriodically drained for (.-) life%.%s*$","La probabilidad de acertar con hechizos y habilidades se reduce un {{1}}%.\nSe drena {{2}} de salud periódicamente."}
T[13444]={"^Deals (.-)%% Nature damage every (.-) sec%.\nMovement and attack speed reduced by (.-)%%%.%s*$","Inflige {{1}}% daño de Naturaleza cada {{2}} seg.\nSe reduce tu velocidad de movimiento y de ataque en {{3}}%."}
T[13445]={"^Rooted in place%.\nTaking (.-) damage periodically%.%s*$","Inmovilizado en el sitio.\nRecibe {{1}} de daño periódicamente."}
T[13446]={"^Reduces physical damage by (.-)%%%.%s*$","Reduce el daño físico un {{1}}%."}
T[13447]={"^Reduces arcane damage by (.-)%%%.%s*$","Reduce el daño de arcano en un {{1}}%."}
T[13448]={"^Movement slowed by (.-)%%%.\n\nStacks up to 3 times%.%s*$","Movimiento ralentizado en {{1}}%.\n\nAcumula hasta 3 veces."}
