T[13535]={"^Healing 170 damage every (.-) seconds%.%s*$","Sana 170 de daño cada {{1}} segundos."}
T[13536]={"^Healing 250 damage every (.-) seconds%.%s*$","Sana 250 de daño cada {{1}} segundos."}
