T[16299]={"^Movement Speed increased by |cffFF9900(.-)%%|r for |cffFF9900(.-)|r after any kill that grants honor or experience%. This effect is removed upon taking damage%.%s*$","La velocidad de movimiento aumenta un |cffFF9900{{1}}%|r durante |cffFF9900{{2}}|r tras cualquier muerte que otorgue honor o experiencia. Este efecto se elimina al recibir daño."}
T[16300]={"^Regenerate |cffFF9900(.-)%%|r of your maximum health every |cffFF9900(.-) second|r for |cffFF9900(.-)|r after any kill that grants honor or experience%.%s*$","Regeneras un |cffFF9900{{1}}%|r de tu salud máxima cada |cffFF9900{{2}} segundo|r durante |cffFF9900{{3}}|r tras cualquier muerte que otorgue honor o experiencia."}
T[16301]={"^Regenerate |cffFF9900(.-)%%|r of your maximum mana after any kill that grants honor or experience%.%s*$","Regenera un |cffFF9900{{1}}%|r de tu maná máximo tras cualquier muerte que otorgue honor o experiencia."}
