T[16999]={"^Receiving (.-) Frost damage every second%. Movement speed reduced by (.-)%%%. Stacks up to 5 times%.%s*$","Recibes {{1}} de daño de Escarcha cada segundo. La velocidad de movimiento se reduce un {{2}}%. Se acumula hasta 5 veces."}
T[17000]={"^Receiving (.-) damage every second%. Movement speed reduced by (.-)%%%. Stack up to 5 times%.%s*$","Recibes {{1}} de daño cada segundo. La velocidad de movimiento se reduce un {{2}}%. Se puede acumular hasta 5 veces."}
T[17001]={"^Summons an overwhelming blizzard%.%s*$","Invoca una ventisca abrumadora."}
T[17002]={"^How cute, it's carrying a banana!%s*$","¡Qué mono, lleva un plátano!"}
T[17003]={"^Increases speed by 100%%%s*$","Aumenta la velocidad un 100%"}
T[17004]={"^Increases speed by 60%%%s*$","Aumenta la velocidad un 60%"}
