T[17311]={"^Elemental Destruction immo Proc SLS%s*$","Activación de inmolación de Destrucción elemental SLS"}
T[17312]={"^Elemental Destruction flame shock Proc SLS%s*$","Activación de Choque de llamas de Destrucción elemental SLS"}
T[17313]={"^274739 refresh sls%s*$","274739 actualiza sls"}
