T[18402]={"^Permanently adds 26 Critical Strike Rating to an item worn on the chest%.  Only usable on items level 65 and above%.%s*$","Añade permanentemente 26 de índice de golpe crítico a un objeto equipado en el pecho. Solo se puede usar en objetos de nivel 65 o superior."}
T[18403]={"^Permanently adds 6 stats to an item worn on the chest%. Only usable on items level 65 and above%.%s*$","Añade permanentemente 6 estadísticas a un objeto de pecho. Solo se puede usar en objetos de nivel 65 o superior."}
T[18404]={"^Permanently adds 8 stats to an item worn on the chest%. Only usable on items level 65 and above%.%s*$","Añade permanentemente 8 estadísticas a un objeto de pecho. Solo se puede usar en objetos de nivel 65 o superior."}
T[18405]={"^Permanently adds 12 Hit Rating to an item worn on the chest%.  Only usable on items level 65 and above%.%s*$","Añade permanentemente 12 de índice de acierto a un objeto de pecho. Solo se puede usar en objetos de nivel 65 o superior."}
