T[19060]={"^You have unlimited mana, energy and rage%.%s*$","Tienes maná, energía y furia ilimitados."}
T[19061]={"^When killing a player, nearby enemies flee in terror%.%s*$","Al matar a un jugador, los enemigos cercanos huyen aterrorizados."}
T[19062]={"^Landing a killing blow on a player makes you level up, increasing your damage and size%.%s*$","Asestar un golpe de muerte a un jugador te hace subir de nivel, aumentando tu daño y tamaño."}
T[19063]={"^Ding! Increases damage done by (.-)%%%. Size increased%.%s*$","¡Ding! El daño infligido aumenta un {{1}}%. El tamaño ha aumentado."}
T[19064]={"^Transformed into a saurok%.%s*$","Te has transformado en un saurok."}
T[19065]={"^Landing a killing blow on a player causes an explosion at their position that knocks enemies back%.%s*$","Asestar un golpe de muerte a un jugador provoca una explosión en su posición que empuja a los enemigos hacia atrás."}
T[19066]={"^You have gained new abilitles%. Unable to use normal spells or abilities%.%s*$","Has obtenido nuevas habilidades. No puedes usar hechizos o habilidades normales."}
T[19067]={"^Increases physical damage done by 10%%%.%s*$","Aumenta el daño físico infligido en un 10%."}
T[19068]={"^Landing a killing blow on an enemy, resets the cooldown of all your abilities%.%s*$","Al asestar un golpe de muerte a un enemigo, se reinicia el tiempo de reutilización de todas tus habilidades."}
T[19069]={"^Transformed into an elemental%.%s*$","Transformado en un elemental."}
T[19070]={"^Transformed into a giant%. Become unstoppable%.%s*$","Transformado en un gigante. Conviértete en imparable."}
