T[20814]={"^Increases the healing of your Healing Stream Totem by (.-)%%%.%s*$","Aumenta la sanación de tu Tótem de corriente de sanación en un {{1}}%."}
T[20815]={"^Restoring Tides Mana Tide SLS%s*$","Marea restauradora SLS"}
T[20816]={"^Your next Windfury deals (.-)%% more threat and damage to creatures%. Lasts (.-)%.%s*$","Tu próximo Viento furioso inflige un {{1}}% más de amenaza y daño a las criaturas. Dura {{2}}."}
T[20817]={"^Kaladin SLS Placeholder%s*$","Kaladin SLS Placeholder"}
T[20818]={"^Allows casting Shadow Artillery while above 3 stacks%.%s*$","Permite lanzar Artillería de Sombras mientras tengas más de 3 acumulaciones."}
T[20819]={"^Your next Wild Growth's range is increased by (.-) yards and heals (.-) additional targets%.\n\nHealing Touch and Regrowth consume up to 2 stacks to reduce their cast time by 50%% per stack consumed%.%s*$","El alcance de tu próximo Crecimiento salvaje aumenta {{1}} metros y sana {{2}} objetivos adicionales.\n\nToque sanador y Recrecimiento consumen hasta 2 acumulaciones para reducir su tiempo de lanzamiento en un 50% por cada acumulación consumida."}
T[20820]={"^Increases the healing received from caster's Medicinal Sting and Grove Medicine by (.-)%%%.%s*$","Aumenta la sanación recibida de Aguijón medicinal y Medicina de la arboleda del lanzador en un {{1}}%."}
